function SoftwareStack({slug}:{slug:string}){
  const groups=softwareBySlug[slug];
  if(!groups)return null;
  return <section className="software-stack-section"><div className="container"><div className="section-intro-grid"><div><p className="eyebrow">Systems we commonly support</p><h2 className="section-title">Your platforms.<br/><em>One managed layer.</em></h2></div><p>Operations Hive teams can work inside client-approved systems, subject to access, training and verified competence. Platform inclusion does not imply a vendor partnership or certification.</p></div><div className="software-groups">{groups.map(group=><article className="software-group" key={group.title}><span className="software-group-label">{group.title}</span><div className="software-grid">{group.systems.map(system=><div className="software-tile" key={system.name}>{system.icon&&localLogoSlugs.has(system.icon)?<img src={`/software-logos/${system.icon}.svg`} alt="" loading="lazy"/>:<span className="software-wordmark" aria-hidden="true">{system.name.split(/\s|\./).map(part=>part[0]).join("").slice(0,3)}</span>}<strong>{system.name}</strong></div>)}</div></article>)}</div><p className="software-boundary"><ShieldCheck size={17}/> We operate approved tools; we do not claim ownership of client platforms or complex software development unless separately scoped.</p></div></section>
}

